# Single-letter shorthand
BASE_COLORS = {
    'b': (0.0, 0.0, 1.0), 'g': (0.0, 0.5, 0.0), 'r': (1.0, 0.0, 0.0),
    'c': (0.0, 0.75, 0.75), 'm': (0.75, 0.0, 0.75), 'y': (0.75, 0.75, 0.0),
    'k': (0.0, 0.0, 0.0), 'w': (1.0, 1.0, 1.0),
}

TABLEAU_COLORS = {
    'tab:blue': '#1f77b4', 'tab:orange': '#ff7f0e', 'tab:green': '#2ca02c',
    'tab:red': '#d62728', 'tab:purple': '#9467bd', 'tab:brown': '#8c564b',
    'tab:pink': '#e377c2', 'tab:gray': '#7f7f7f', 'tab:olive': '#bcbd22',
    'tab:cyan': '#17becf',
}

cnames = CSS4_COLORS  # backward compat alias


def _hex_to_rgba(h):
    """Parse hex string to (r, g, b, a) floats in [0,1]."""
    h = h.lstrip('#')
    if len(h) == 3:
        h = h[0]*2 + h[1]*2 + h[2]*2
    if len(h) == 4:
        h = h[0]*2 + h[1]*2 + h[2]*2 + h[3]*2
    r = int(h[0:2], 16) / 255.0
    g = int(h[2:4], 16) / 255.0
    b = int(h[4:6], 16) / 255.0
    a = int(h[6:8], 16) / 255.0 if len(h) >= 8 else 1.0
    return (r, g, b, a)


def is_color_like(c):
    """Return True if c looks like a valid matplotlib color spec."""
    try:
        to_rgba(c)
        return True
    except (ValueError, TypeError):
        return False


def to_hex(c, keep_alpha=False):
    """Convert a color to hex string."""
    rgba = to_rgba(c)
    if keep_alpha:
        return '#{:02X}{:02X}{:02X}{:02X}'.format(
            int(rgba[0]*255), int(rgba[1]*255), int(rgba[2]*255), int(rgba[3]*255))
    return '#{:02X}{:02X}{:02X}'.format(
        int(rgba[0]*255), int(rgba[1]*255), int(rgba[2]*255))


def to_rgb(c):
    """Convert a color to (r, g, b) tuple."""
    return to_rgba(c)[:3]


def to_rgba(c, alpha=None):
    """Convert any matplotlib color spec to (r, g, b, a) tuple.

    Accepts: single-letter codes, named colors, hex strings, RGB/RGBA tuples,
    'C0'-'C9' cycle colors, 'none'/'None' for transparent.
    """
    if c is None or (isinstance(c, str) and c.lower() == 'none'):
        return (0.0, 0.0, 0.0, 0.0)

    if isinstance(c, str):
        cl = c.lower().strip()
        # Single-letter shorthand
        if cl in BASE_COLORS:
            rgb = BASE_COLORS[cl]
            a = alpha if alpha is not None else 1.0
            return rgb + (a,)
        # CN color cycle notation
        if len(cl) == 2 and cl[0] == 'c' and cl[1].isdigit():
            cycle = ['#1f77b4','#ff7f0e','#2ca02c','#d62728','#9467bd',
                     '#8c564b','#e377c2','#7f7f7f','#bcbd22','#17becf']
            rgba = _hex_to_rgba(cycle[int(cl[1])])
            if alpha is not None:
                rgba = rgba[:3] + (alpha,)
            return rgba
        # Hex color
        if c.startswith('#'):
            rgba = _hex_to_rgba(c)
            if alpha is not None:
                rgba = rgba[:3] + (alpha,)
            return rgba
        # Named colors
        if cl in CSS4_COLORS:
            rgba = _hex_to_rgba(CSS4_COLORS[cl])
            if alpha is not None:
                rgba = rgba[:3] + (alpha,)
            return rgba
        if c in CSS4_COLORS:
            rgba = _hex_to_rgba(CSS4_COLORS[c])
            if alpha is not None:
                rgba = rgba[:3] + (alpha,)
            return rgba
        # Gray level as string: '0.5'
        try:
            g = float(cl)
            if 0 <= g <= 1:
                a = alpha if alpha is not None else 1.0
                return (g, g, g, a)
        except ValueError:
            pass
        raise ValueError(f"Invalid color: {c!r}")

    if isinstance(c, (tuple, list, _np.ndarray)):
        t = tuple(float(x) for x in c)
        if len(t) == 3:
            t = t + (1.0,)
        elif len(t) == 4:
            pass
        elif len(t) == 1:
            t = (t[0], t[0], t[0], 1.0)
        else:
            t = t[:4]
        if alpha is not None:
            t = t[:3] + (alpha,)
        return t

    if isinstance(c, (int, float, _np.integer, _np.floating)):
        g = float(c)
        a = alpha if alpha is not None else 1.0
        return (g, g, g, a)

    raise ValueError(f"Invalid color: {c!r}")


def to_rgba_array(c, alpha=None):
    """Convert an array of colors to Nx4 RGBA array."""
    if isinstance(c, _np.ndarray) and c.ndim == 2 and c.shape[1] in (3, 4):
        out = _np.ones((c.shape[0], 4))
        out[:, :c.shape[1]] = c
        if alpha is not None:
            out[:, 3] = alpha
        return out
    if isinstance(c, str):
        return _np.array([to_rgba(c, alpha)])
    try:
        result = _np.array([to_rgba(ci, alpha) for ci in c])
        return result
    except (TypeError, ValueError):
        return _np.array([to_rgba(c, alpha)])


# ── Normalization classes ───────────────────────────────────────

import sys as _colors_sys

_colors_warned = set()

def _colors_getattr_fallback(self, name):
    if name.startswith('_'):
        raise AttributeError(name)
    key = f'{type(self).__name__}.{name}'
    if key not in _colors_warned:
        _colors_warned.add(key)
        try:
            _colors_sys.__stderr__.write(
                f"[mpl-shim] colors.{key}() not implemented — returning None\n")
        except Exception:
            pass
    def _noop(*args, **kwargs): return None
    return _noop


class Normalize:
    """Linear normalization mapping [vmin, vmax] to [0, 1]."""
    __getattr__ = _colors_getattr_fallback

    def __init__(self, vmin=None, vmax=None, clip=False):
        self.vmin = vmin
        self.vmax = vmax
        self.clip = clip

    def __call__(self, value, clip=None):
        value = _np.asarray(value, dtype=float)
        vmin = self.vmin if self.vmin is not None else _np.nanmin(value)
        vmax = self.vmax if self.vmax is not None else _np.nanmax(value)
        denom = max(vmax - vmin, 1e-10)
        result = (value - vmin) / denom
        if clip or self.clip:
            result = _np.clip(result, 0, 1)
        return result

    def inverse(self, value):
        vmin = self.vmin if self.vmin is not None else 0
        vmax = self.vmax if self.vmax is not None else 1
        return vmin + _np.asarray(value) * (vmax - vmin)

    def autoscale(self, A):
        A = _np.asarray(A)
        self.vmin = float(_np.nanmin(A))
        self.vmax = float(_np.nanmax(A))

    def autoscale_None(self, A):
        A = _np.asarray(A)
        if self.vmin is None:
            self.vmin = float(_np.nanmin(A))
        if self.vmax is None:
            self.vmax = float(_np.nanmax(A))

    def scaled(self):
        return self.vmin is not None and self.vmax is not None


class LogNorm(Normalize):
    """Logarithmic normalization. Mirrors upstream:
    forward = (log(x) - log(vmin)) / (log(vmax) - log(vmin)).
    Values ≤ 0 yield NaN (matching upstream's masked-array behaviour)."""

    def autoscale(self, A):
        a = _np.asarray(A, dtype=float)
        pos = a[a > 0]
        self.vmin = float(_np.nanmin(pos)) if pos.size else 1.0
        self.vmax = float(_np.nanmax(pos)) if pos.size else 10.0

    def autoscale_None(self, A):
        a = _np.asarray(A, dtype=float)
        pos = a[a > 0]
        if self.vmin is None:
            self.vmin = float(_np.nanmin(pos)) if pos.size else 1.0
        if self.vmax is None:
            self.vmax = float(_np.nanmax(pos)) if pos.size else 10.0

    def __call__(self, value, clip=None):
        value = _np.asarray(value, dtype=float)
        vmin = self.vmin if self.vmin is not None else float(
            _np.nanmin(value[value > 0])) if _np.any(value > 0) else 1.0
        vmax = self.vmax if self.vmax is not None else float(_np.nanmax(value))
        if vmin <= 0 or vmax <= 0 or vmax <= vmin:
            return _np.zeros_like(value)
        with _np.errstate(divide='ignore', invalid='ignore'):
            log_v = _np.log10(_np.where(value > 0, value, _np.nan))
            result = (log_v - _np.log10(vmin)) / (_np.log10(vmax) - _np.log10(vmin))
        if clip or self.clip:
            result = _np.clip(result, 0.0, 1.0)
        return result

    def inverse(self, value):
        value = _np.asarray(value, dtype=float)
        vmin = self.vmin if self.vmin is not None else 1.0
        vmax = self.vmax if self.vmax is not None else 10.0
        return _np.power(10.0,
                         value * (_np.log10(vmax) - _np.log10(vmin))
                         + _np.log10(vmin))


class SymLogNorm(Normalize):
    """Symmetric log normalization — linear inside [-linthresh, +linthresh],
    log-scaled outside. Identical math to upstream:

        s(x) = sign(x) · linthresh · (linscale + log(|x|/linthresh))   if |x| > linthresh
        s(x) = x · linscale                                            otherwise

    then linearly mapped to [0, 1] using s(vmin)..s(vmax).
    """

    def __init__(self, linthresh, linscale=1.0, vmin=None, vmax=None,
                 clip=False, base=10):
        super().__init__(vmin, vmax, clip)
        self.linthresh = float(linthresh)
        self.linscale = float(linscale)
        self.base = base
        # Effective linear-region slope so the function is continuous at ±linthresh.
        self._linscale_adj = self.linscale / (1.0 - 1.0 / float(base))

    def _transform(self, value):
        v = _np.asarray(value, dtype=float)
        lt = self.linthresh
        log_base = _np.log(self.base)
        abs_v = _np.abs(v)
        # Mask out values inside the linear region so log(0) never fires.
        # We compute both branches anyway; the where() picks the safe one.
        with _np.errstate(divide='ignore', invalid='ignore'):
            safe_abs = _np.where(abs_v > lt, abs_v, lt)  # avoid log(0)
            log_part = _np.sign(v) * lt * (
                self._linscale_adj + _np.log(safe_abs / lt) / log_base)
        out = _np.where(abs_v > lt, log_part, v * self._linscale_adj)
        return out

    def _inverse_transform(self, value):
        v = _np.asarray(value, dtype=float)
        lt = self.linthresh
        log_base = _np.log(self.base)
        thresh = lt * self._linscale_adj
        abs_v = _np.abs(v)
        with _np.errstate(over='ignore', invalid='ignore'):
            exp_part = _np.sign(v) * lt * _np.exp(
                log_base * (abs_v / lt - self._linscale_adj))
        out = _np.where(abs_v > thresh, exp_part, v / self._linscale_adj)
        return out

    def __call__(self, value, clip=None):
        value = _np.asarray(value, dtype=float)
        vmin = self.vmin if self.vmin is not None else float(_np.nanmin(value))
        vmax = self.vmax if self.vmax is not None else float(_np.nanmax(value))
        s_min = self._transform(vmin)
        s_max = self._transform(vmax)
        denom = s_max - s_min
        if denom == 0:
            return _np.zeros_like(value)
        result = (self._transform(value) - s_min) / denom
        if clip or self.clip:
            result = _np.clip(result, 0.0, 1.0)
        return result

    def inverse(self, value):
        value = _np.asarray(value, dtype=float)
        vmin = self.vmin if self.vmin is not None else -1.0
        vmax = self.vmax if self.vmax is not None else 1.0
        s_min = self._transform(vmin)
        s_max = self._transform(vmax)
        return self._inverse_transform(value * (s_max - s_min) + s_min)


class PowerNorm(Normalize):
    """Power-law normalization: ``((x − vmin) / (vmax − vmin)) ^ gamma``."""

    def __init__(self, gamma, vmin=None, vmax=None, clip=False):
        super().__init__(vmin, vmax, clip)
        self.gamma = float(gamma)

    def __call__(self, value, clip=None):
        value = _np.asarray(value, dtype=float)
        vmin = self.vmin if self.vmin is not None else float(_np.nanmin(value))
        vmax = self.vmax if self.vmax is not None else float(_np.nanmax(value))
        if vmax == vmin:
            return _np.zeros_like(value)
        # Normalise to [0, 1] first, then raise to gamma. Negative inputs are
        # clipped to 0 to keep the power well-defined (matches upstream).
        x = (value - vmin) / (vmax - vmin)
        x = _np.clip(x, 0.0, None)
        result = _np.power(x, self.gamma)
        if clip or self.clip:
            result = _np.clip(result, 0.0, 1.0)
        return result

    def inverse(self, value):
        value = _np.asarray(value, dtype=float)
        vmin = self.vmin if self.vmin is not None else 0.0
        vmax = self.vmax if self.vmax is not None else 1.0
        return vmin + _np.power(_np.clip(value, 0.0, None),
                                 1.0 / self.gamma) * (vmax - vmin)


class BoundaryNorm(Normalize):
    """Map continuous values to discrete colour-table indices defined by
    monotonically-increasing boundaries.

    Mirrors upstream:
      idx = digitize(value, boundaries) − 1   (0…len(b)−2)
    then scaled into [0, 1] using the chosen ncolors. With ``extend='min'``
    or ``'max'`` (or ``'both'``) the under/over regions consume one slot.
    """

    def __init__(self, boundaries, ncolors, clip=False, *, extend='neither'):
        self.boundaries = _np.asarray(boundaries, dtype=float)
        self.ncolors = int(ncolors)
        self.clip = bool(clip)
        self.extend = extend
        self.vmin = float(self.boundaries[0])
        self.vmax = float(self.boundaries[-1])
        self.N = int(ncolors)
        # Number of "real" regions between boundaries.
        self._n_regions = len(self.boundaries) - 1
        # How many extension slots we reserve at each end.
        self._extend_under = extend in ('min', 'both')
        self._extend_over = extend in ('max', 'both')
        self._n_used = (self._n_regions
                        + int(self._extend_under) + int(self._extend_over))

    def __call__(self, value, clip=None):
        value = _np.asarray(value, dtype=float)
        # digitize returns index i such that b[i-1] <= v < b[i].
        idx = _np.digitize(value, self.boundaries) - 1
        # Anything below the first boundary becomes −1.
        # Above the last boundary becomes len(b)−1.
        max_real = self._n_regions - 1
        if self._extend_under:
            idx = _np.where(value < self.boundaries[0], -1, idx)
        else:
            idx = _np.where(value < self.boundaries[0], 0, idx)
        if self._extend_over:
            idx = _np.where(value >= self.boundaries[-1], max_real + 1, idx)
        else:
            idx = _np.where(value >= self.boundaries[-1], max_real, idx)
        # Shift indices so under-extend (-1) becomes 0.
        offset = 1 if self._extend_under else 0
        idx = idx + offset
        idx = _np.clip(idx, 0, self._n_used - 1)
        # Map to colour-table index [0, ncolors-1] then to [0, 1].
        scale = (self.ncolors - 1) / max(self._n_used - 1, 1)
        ci = (idx * scale).astype(int)
        ci = _np.clip(ci, 0, self.ncolors - 1)
        if clip or self.clip:
            ci = _np.clip(ci, 0, self.ncolors - 1)
        return ci / max(self.ncolors - 1, 1)

    def inverse(self, value):
        # BoundaryNorm is not strictly invertible — upstream raises. We
        # approximate by returning the midpoint of the matching region.
        value = _np.asarray(value, dtype=float)
        ci = _np.clip((value * (self.ncolors - 1)).astype(int),
                      0, self._n_used - 1)
        offset = 1 if self._extend_under else 0
        idx = _np.clip(ci - offset, 0, self._n_regions - 1)
        mids = 0.5 * (self.boundaries[:-1] + self.boundaries[1:])
        return mids[idx]


class TwoSlopeNorm(Normalize):
    """Normalization with different rates above and below a center value."""

    def __init__(self, vcenter, vmin=None, vmax=None):
        super().__init__(vmin, vmax)
        self.vcenter = vcenter

    def __call__(self, value, clip=None):
        value = _np.asarray(value, dtype=float)
        vmin = self.vmin if self.vmin is not None else _np.nanmin(value)
        vmax = self.vmax if self.vmax is not None else _np.nanmax(value)
        result = _np.where(
            value < self.vcenter,
            0.5 * (value - vmin) / max(self.vcenter - vmin, 1e-10),
            0.5 + 0.5 * (value - self.vcenter) / max(vmax - self.vcenter, 1e-10)
        )
        return _np.clip(result, 0, 1)


# Legacy alias
DivergingNorm = TwoSlopeNorm
CenteredNorm = TwoSlopeNorm


class NoNorm(Normalize):
    """Identity normalization."""

    def __call__(self, value, clip=None):
        return _np.asarray(value, dtype=float)


class FuncNorm(Normalize):
    """Normalization via user-supplied functions."""

    def __init__(self, functions, vmin=None, vmax=None):
        super().__init__(vmin, vmax)
        self._forward, self._inverse = functions

    def __call__(self, value, clip=None):
        return self._forward(_np.asarray(value, dtype=float))


# ── Colormap classes (mostly delegating to cm module) ───────────

class ListedColormap:
    """Map indices to colors from a discrete list."""

    def __init__(self, colors, name='custom', N=None):
        self.colors = list(colors)
        self.name = name
        self.N = N or len(self.colors)

    def __call__(self, X, alpha=None, bytes=False):
        X = _np.asarray(X, dtype=float)
        idx = _np.clip((_np.asarray(X) * (len(self.colors) - 1)).astype(int),
                       0, len(self.colors) - 1)
        if X.ndim == 0:
            c = self.colors[int(idx)]
            rgba = to_rgba(c, alpha)
            if bytes:
                return tuple(int(v * 255) for v in rgba)
            return rgba
        result = _np.array([to_rgba(self.colors[i], alpha) for i in idx.ravel()])
        result = result.reshape(X.shape + (4,))
        if bytes:
            return (_np.clip(result, 0, 1) * 255).astype(_np.uint8)
        return result

    def reversed(self, name=None):
        return ListedColormap(list(reversed(self.colors)), name or self.name + '_r')


class LinearSegmentedColormap:
    """Colormap from linear segments."""

    def __init__(self, name, segmentdata, N=256, gamma=1.0):
        self.name = name
        self._segmentdata = segmentdata
        self.N = N
        # Build lookup table from segment data
        self._lut = _np.zeros((N, 4))
        for ci, channel in enumerate(['red', 'green', 'blue']):
            if channel in segmentdata:
                anchors = _np.array(segmentdata[channel])
                x = _np.linspace(0, 1, N)
                for i, xi in enumerate(x):
                    idx = _np.searchsorted(anchors[:, 0], xi) - 1
                    idx = max(0, min(idx, len(anchors) - 2))
                    x0, y0, y1 = anchors[idx]
                    x1, y0b, y1b = anchors[idx + 1]
                    t = (xi - x0) / max(x1 - x0, 1e-10)
                    self._lut[i, ci] = y1 * (1 - t) + y0b * t
        self._lut[:, 3] = 1.0

    def __call__(self, X, alpha=None, bytes=False):
        X = _np.asarray(X, dtype=float)
        idx = _np.clip((X * (self.N - 1)).astype(int), 0, self.N - 1)
        result = self._lut[idx.ravel()].reshape(X.shape + (4,))
        if alpha is not None:
            result[..., 3] = alpha
        if bytes:
            return (_np.clip(result, 0, 1) * 255).astype(_np.uint8)
        return result

    def reversed(self, name=None):
        rev_data = {}
        for key in self._segmentdata:
            anchors = self._segmentdata[key]
            rev_data[key] = [(1.0 - x, y1, y0) for x, y0, y1 in reversed(anchors)]
        return LinearSegmentedColormap(name or self.name + '_r', rev_data, self.N)

    @staticmethod
    def from_list(name, colors, N=256, gamma=1.0):
        """Create a colormap from a list of colors."""
        return ListedColormap(colors, name, N)


