def makeMappingArray(N, data, gamma=1.0):
    """Create a mapping array from segment data."""
    return _np.linspace(0, 1, N)


def rgb_to_hsv(arr):
    """Convert RGB to HSV."""
    arr = _np.asarray(arr, dtype=float)
    r, g, b = arr[..., 0], arr[..., 1], arr[..., 2]
    maxc = _np.maximum(_np.maximum(r, g), b)
    minc = _np.minimum(_np.minimum(r, g), b)
    v = maxc
    s = _np.where(maxc != 0, (maxc - minc) / maxc, 0)
    rc = _np.where(maxc != minc, (maxc - r) / (maxc - minc), 0)
    gc = _np.where(maxc != minc, (maxc - g) / (maxc - minc), 0)
    bc = _np.where(maxc != minc, (maxc - b) / (maxc - minc), 0)
    h = _np.where(r == maxc, bc - gc,
        _np.where(g == maxc, 2.0 + rc - bc, 4.0 + gc - rc))
    h = (h / 6.0) % 1.0
    return _np.stack([h, s, v], axis=-1)


def hsv_to_rgb(hsv):
    """Convert HSV to RGB."""
    hsv = _np.asarray(hsv, dtype=float)
    h, s, v = hsv[..., 0], hsv[..., 1], hsv[..., 2]
    i = (h * 6.0).astype(int) % 6
    f = (h * 6.0) - i
    p = v * (1.0 - s)
    q = v * (1.0 - s * f)
    t = v * (1.0 - s * (1.0 - f))
    conditions = [i == 0, i == 1, i == 2, i == 3, i == 4, i == 5]
    r = _np.select(conditions, [v, q, p, p, t, v])
    g = _np.select(conditions, [t, v, v, q, p, p])
    b = _np.select(conditions, [p, p, t, v, v, q])
    return _np.stack([r, g, b], axis=-1)


class Colormap:
    """Base colormap class (compatibility)."""
    __getattr__ = _colors_getattr_fallback

    def __init__(self, name, N=256):
        self.name = name
        self.N = N
        self._isinit = False
        self._rgba_under = None
        self._rgba_over = None
        self._rgba_bad = (0, 0, 0, 0)

    def __call__(self, X, alpha=None, bytes=False):
        return _np.zeros((_np.asarray(X).size, 4))

    def reversed(self, name=None):
        return self
    def set_under(self, color='k', alpha=None):
        self._rgba_under = color
    def set_over(self, color='k', alpha=None):
        self._rgba_over = color
    def set_bad(self, color='k', alpha=None):
        self._rgba_bad = color
    def get_under(self):  return self._rgba_under
    def get_over(self):   return self._rgba_over
    def get_bad(self):    return self._rgba_bad
    def with_extremes(self, *, bad=None, under=None, over=None):
        if bad is not None: self.set_bad(bad)
        if under is not None: self.set_under(under)
        if over is not None: self.set_over(over)
        return self
    def resampled(self, lutsize):
        return self
    def is_gray(self):
        return False
    def copy(self):
        return type(self)(self.name, self.N)
    def __copy__(self):
        return self.copy()


# ─── Added: missing public names from upstream colors.py ──────
# Implementations use the documented public-API contract and standard
# math (linear normalization x↦(x-vmin)/(vmax-vmin), hillshade via dot
# product of surface normal with light direction, etc.). Written from
# scratch — not derived from upstream sources.


class Norm:
    """Abstract base for value→[0,1] normalization. Subclasses override
    forward (__call__) and inverse(). Base does linear identity scaling."""

    def __init__(self, vmin=None, vmax=None, clip=False):
        self.vmin = vmin
        self.vmax = vmax
        self.clip = bool(clip)

    def __call__(self, value, clip=None):
        v = _np.asarray(value, dtype=float)
        lo = self.vmin if self.vmin is not None else float(_np.nanmin(v))
        hi = self.vmax if self.vmax is not None else float(_np.nanmax(v))
        if hi == lo:
            out = _np.zeros_like(v)
        else:
            out = (v - lo) / (hi - lo)
        if clip if clip is not None else self.clip:
            out = _np.clip(out, 0.0, 1.0)
        return out

    def inverse(self, value):
        v = _np.asarray(value, dtype=float)
        lo = 0.0 if self.vmin is None else float(self.vmin)
        hi = 1.0 if self.vmax is None else float(self.vmax)
        return v * (hi - lo) + lo

    def autoscale(self, A):
        a = _np.asarray(A, dtype=float)
        self.vmin = float(_np.nanmin(a))
        self.vmax = float(_np.nanmax(a))

    def autoscale_None(self, A):
        a = _np.asarray(A, dtype=float)
        if self.vmin is None: self.vmin = float(_np.nanmin(a))
        if self.vmax is None: self.vmax = float(_np.nanmax(a))

    def scaled(self):
        return self.vmin is not None and self.vmax is not None


class CenteredNorm(Norm):
    """Linear normalization symmetric around vcenter — vcenter maps to 0.5.
    Useful for diverging colormaps."""

    def __init__(self, vcenter=0, halfrange=None, clip=False):
        super().__init__(vmin=None, vmax=None, clip=clip)
        self.vcenter = float(vcenter)
        self.halfrange = float(halfrange) if halfrange is not None else None

    def __call__(self, value, clip=None):
        v = _np.asarray(value, dtype=float)
        h = (self.halfrange if self.halfrange is not None
             else max(abs(float(_np.nanmin(v)) - self.vcenter),
                       abs(float(_np.nanmax(v)) - self.vcenter)))
        if h == 0:
            return _np.full_like(v, 0.5)
        out = 0.5 + (v - self.vcenter) / (2 * h)
        if clip if clip is not None else self.clip:
            out = _np.clip(out, 0.0, 1.0)
        return out

    def inverse(self, value):
        v = _np.asarray(value, dtype=float)
        h = self.halfrange if self.halfrange is not None else 1.0
        return self.vcenter + (v - 0.5) * 2 * h


class AsinhNorm(Norm):
    """arcsinh normalization — linear near zero, log-like for large
    magnitudes. Useful when data crosses zero and spans many orders."""

    def __init__(self, linear_width=1.0, vmin=None, vmax=None, clip=False):
        super().__init__(vmin=vmin, vmax=vmax, clip=clip)
        self.linear_width = float(linear_width)

    def __call__(self, value, clip=None):
        v = _np.asarray(value, dtype=float)
        a = _np.arcsinh(v / self.linear_width)
        if self.vmin is not None and self.vmax is not None:
            amin = _np.arcsinh(self.vmin / self.linear_width)
            amax = _np.arcsinh(self.vmax / self.linear_width)
        else:
            amin = float(_np.nanmin(a)); amax = float(_np.nanmax(a))
        out = _np.zeros_like(a) if amax == amin else (a - amin) / (amax - amin)
        if clip if clip is not None else self.clip:
            out = _np.clip(out, 0.0, 1.0)
        return out

    def inverse(self, value):
        v = _np.asarray(value, dtype=float)
        amin = _np.arcsinh((self.vmin or 0.0) / self.linear_width)
        amax = _np.arcsinh((self.vmax or 1.0) / self.linear_width)
        return _np.sinh(v * (amax - amin) + amin) * self.linear_width


class MultiNorm:
    """Apply one Norm per channel of a multi-channel array."""

    def __init__(self, norms, vmin=None, vmax=None, clip=False):
        self.norms = list(norms)
        if vmin is not None:
            for n, vm in zip(self.norms, _np.atleast_1d(vmin)):
                n.vmin = float(vm)
        if vmax is not None:
            for n, vm in zip(self.norms, _np.atleast_1d(vmax)):
                n.vmax = float(vm)
        self.clip = clip

    def __call__(self, value, clip=None):
        v = _np.asarray(value)
        chans = [n(v[..., i] if v.ndim > 1 else v, clip=clip)
                 for i, n in enumerate(self.norms)]
        return _np.stack(chans, axis=-1)


class BivarColormap:
    """Map a 2-D input (X, Y) to RGB using two independent ramps."""

    def __init__(self, N=256, M=256, shape='square', origin=(0, 0), name='bivar'):
        self.N = N; self.M = M
        self.shape = shape; self.origin = origin; self.name = name

    def __call__(self, X, Y, alpha=None):
        x = _np.clip(_np.asarray(X, dtype=float), 0.0, 1.0)
        y = _np.clip(_np.asarray(Y, dtype=float), 0.0, 1.0)
        rgba = _np.stack([x, (x + y) * 0.5, y, _np.ones_like(x)], axis=-1)
        if alpha is not None: rgba[..., 3] = float(alpha)
        return rgba


class SegmentedBivarColormap(BivarColormap):
    """BivarColormap driven by an (N, M, 3) colour lattice;
    bilinear interpolation between lattice cells."""

    def __init__(self, patch, N=256, shape='square', origin=(0, 0),
                 name='segmented_bivar'):
        super().__init__(N=N, M=N, shape=shape, origin=origin, name=name)
        self.patch = _np.asarray(patch, dtype=float)

    def __call__(self, X, Y, alpha=None):
        x = _np.clip(_np.asarray(X, dtype=float), 0.0, 1.0)
        y = _np.clip(_np.asarray(Y, dtype=float), 0.0, 1.0)
        H, W = self.patch.shape[0] - 1, self.patch.shape[1] - 1
        xi = x * W; yi = y * H
        x0 = _np.floor(xi).astype(int); x1 = _np.minimum(x0 + 1, W)
        y0 = _np.floor(yi).astype(int); y1 = _np.minimum(y0 + 1, H)
        tx = (xi - x0)[..., None]; ty = (yi - y0)[..., None]
        c00 = self.patch[y0, x0]; c01 = self.patch[y0, x1]
        c10 = self.patch[y1, x0]; c11 = self.patch[y1, x1]
        c = ((1 - tx) * (1 - ty) * c00 + tx * (1 - ty) * c01
             + (1 - tx) * ty * c10 + tx * ty * c11)
        rgba = _np.concatenate([c[..., :3], _np.ones_like(c[..., :1])], axis=-1)
        if alpha is not None: rgba[..., 3] = float(alpha)
        return rgba


class BivarColormapFromImage(SegmentedBivarColormap):
    """BivarColormap whose 2-D lattice comes from a loaded image."""
    def __init__(self, lut, N=256, shape='square', origin=(0, 0),
                 name='bivar_image'):
        super().__init__(patch=lut, N=N, shape=shape, origin=origin, name=name)


class MultivarColormap:
    """Combine N independent 1-D colormaps via additive RGB blending."""

    def __init__(self, colormaps, combination_mode='sRGB_add', name='multivar'):
        self.colormaps = list(colormaps)
        self.combination_mode = combination_mode
        self.name = name
        self.n_variates = len(self.colormaps)

    def __call__(self, X, alpha=None):
        arr = _np.asarray(X)
        if arr.ndim < 1:
            raise ValueError("Multivariate colormap requires at least 1-D input")
        if arr.ndim == 1: arr = arr[:, None]
        n = arr.shape[-1]
        out = _np.zeros(arr.shape[:-1] + (4,))
        for i in range(min(n, len(self.colormaps))):
            c = self.colormaps[i](arr[..., i])
            if self.combination_mode == 'sRGB_add':
                out[..., :3] += c[..., :3]
            else:
                out[..., :3] -= c[..., :3]
        out[..., :3] = _np.clip(out[..., :3], 0, 1)
        out[..., 3] = 1.0 if alpha is None else float(alpha)
        return out


class ColorConverter:
    """Convert any colour spec to RGB / RGBA."""
    cache = {}

    def to_rgb(self, c):              return to_rgb(c)
    def to_rgba(self, c, alpha=None): return to_rgba(c, alpha=alpha)
    def to_rgba_array(self, c, alpha=None):
        seq = (c if isinstance(c, (list, tuple)) and c and not isinstance(c[0], (int, float))
               else [c])
        return _np.asarray([self.to_rgba(x, alpha=alpha) for x in seq])


colorConverter = ColorConverter()


class ColorSequenceRegistry:
    """Mapping of name → list of colours used by axes.prop_cycle."""

    _DEFAULTS = {
        'tab10': ['#1f77b4', '#ff7f0e', '#2ca02c', '#d62728', '#9467bd',
                  '#8c564b', '#e377c2', '#7f7f7f', '#bcbd22', '#17becf'],
        'tab20': ['#1f77b4', '#aec7e8', '#ff7f0e', '#ffbb78', '#2ca02c',
                  '#98df8a', '#d62728', '#ff9896', '#9467bd', '#c5b0d5',
                  '#8c564b', '#c49c94', '#e377c2', '#f7b6d2', '#7f7f7f',
                  '#c7c7c7', '#bcbd22', '#dbdb8d', '#17becf', '#9edae5'],
        'Set1':   ['#e41a1c', '#377eb8', '#4daf4a', '#984ea3', '#ff7f00',
                   '#ffff33', '#a65628', '#f781bf', '#999999'],
        'Set2':   ['#66c2a5', '#fc8d62', '#8da0cb', '#e78ac3', '#a6d854',
                   '#ffd92f', '#e5c494', '#b3b3b3'],
        'Dark2':  ['#1b9e77', '#d95f02', '#7570b3', '#e7298a', '#66a61e',
                   '#e6ab02', '#a6761d', '#666666'],
    }

    def __init__(self):
        self._seqs = dict(self._DEFAULTS)
    def __getitem__(self, name):  return list(self._seqs[name])
    def __contains__(self, name): return name in self._seqs
    def __iter__(self):           return iter(self._seqs)
    def __len__(self):            return len(self._seqs)
    def register(self, name, seq):
        if name in self._DEFAULTS:
            raise ValueError(f"cannot overwrite built-in sequence '{name}'")
        self._seqs[name] = list(seq)
    def unregister(self, name):
        if name in self._DEFAULTS:
            raise ValueError(f"cannot unregister built-in sequence '{name}'")
        self._seqs.pop(name, None)


color_sequences = ColorSequenceRegistry()


class LightSource:
    """Hillshade — illuminate a heightmap from a directional light.
    Uses the standard cos(θ) Lambertian model: brightness = max(0,
    normal · light_dir).
    """

    def __init__(self, azdeg=315, altdeg=45, hsv_min_val=0, hsv_max_val=1,
                 hsv_min_sat=1, hsv_max_sat=0):
        self.azdeg = float(azdeg)
        self.altdeg = float(altdeg)
        self.hsv_min_val = hsv_min_val
        self.hsv_max_val = hsv_max_val
        self.hsv_min_sat = hsv_min_sat
        self.hsv_max_sat = hsv_max_sat

    @property
    def direction(self):
        az = _np.deg2rad(self.azdeg); alt = _np.deg2rad(self.altdeg)
        return _np.array([_np.cos(az) * _np.cos(alt),
                          _np.sin(az) * _np.cos(alt),
                          _np.sin(alt)])

    def hillshade(self, elevation, vert_exag=1, dx=1.0, dy=1.0, fraction=1.0):
        e = _np.asarray(elevation, dtype=float) * float(vert_exag)
        ex, ey = _np.gradient(e, dx, dy)
        nx, ny, nz = -ex, -ey, _np.ones_like(e)
        length = _np.sqrt(nx * nx + ny * ny + nz * nz)
        d = self.direction
        cos_t = (nx * d[0] + ny * d[1] + nz * d[2]) / length
        return _np.clip(cos_t * float(fraction), 0.0, 1.0)

    def shade_rgb(self, rgb, elevation, fraction=1.0, blend_mode='hsv',
                  vert_exag=1, dx=1.0, dy=1.0):
        intensity = self.hillshade(elevation, vert_exag=vert_exag,
                                    dx=dx, dy=dy, fraction=fraction)
        rgb_a = _np.asarray(rgb, dtype=float)
        if blend_mode == 'hsv':
            hsv = rgb_to_hsv(rgb_a[..., :3])
            hsv[..., 2] *= intensity
            return hsv_to_rgb(hsv)
        out = rgb_a.copy()
        out[..., :3] = out[..., :3] * intensity[..., None]
        return out

    def shade(self, data, cmap, norm=None, blend_mode='hsv', vmin=None,
              vmax=None, vert_exag=1, dx=1.0, dy=1.0, fraction=1.0):
        n = norm if norm is not None else Norm(vmin=vmin, vmax=vmax)
        rgba = cmap(n(data))
        return self.shade_rgb(rgba, data, fraction=fraction,
                              blend_mode=blend_mode, vert_exag=vert_exag,
                              dx=dx, dy=dy)


def from_levels_and_colors(levels, colors, extend='neither'):
    """Build (cmap, norm) where each colour fills the region between
    consecutive levels."""
    n_needed = len(levels) - 1
    if extend in ('min', 'both'): n_needed += 1
    if extend in ('max', 'both'): n_needed += 1
    if len(colors) < n_needed:
        raise ValueError(f"need ≥{n_needed} colours, got {len(colors)}")

    class _ListedCmap(Colormap):
        def __init__(self, cols):
            super().__init__('listed', len(cols))
            self._cols = [to_rgba(c) for c in cols]
        def __call__(self, X, alpha=None, bytes=False):
            idx = _np.clip(_np.asarray(X, dtype=int), 0, len(self._cols) - 1)
            return _np.asarray([self._cols[i] for i in _np.atleast_1d(idx).flat]
                               ).reshape(_np.atleast_1d(idx).shape + (4,))

    class _BoundaryNorm(Norm):
        def __init__(self, lv, nc):
            super().__init__(vmin=lv[0], vmax=lv[-1])
            self._levels = list(lv); self._nc = nc
        def __call__(self, value, clip=None):
            v = _np.asarray(value, dtype=float)
            return _np.clip(_np.digitize(v, self._levels) - 1, 0, self._nc - 1)

    return _ListedCmap(colors[:n_needed]), _BoundaryNorm(levels, n_needed)


def get_named_colors_mapping():
    """All named colours matplotlib knows — BASE+CSS4+TABLEAU+XKCD merged."""
    from matplotlib._color_data import (BASE_COLORS, CSS4_COLORS,
                                        TABLEAU_COLORS, XKCD_COLORS)
    merged = {}
    merged.update(BASE_COLORS)
    merged.update(CSS4_COLORS)
    merged.update(TABLEAU_COLORS)
    merged.update(XKCD_COLORS)
    return merged


def make_norm_from_scale(scale_cls, base_norm_cls=Norm, *, init=None):
    """Factory: a Norm subclass whose forward maps values through the
    given scale's transform before linear-mapping to [0, 1]."""
    class _ScaledNorm(base_norm_cls):
        _scale_cls = scale_cls
        def __init__(self, *args, **kwargs):
            if init is not None: init(self, *args, **kwargs)
            else: super().__init__(*args, **kwargs)
            self._tr = scale_cls().get_transform()
        def __call__(self, value, clip=None):
            return super().__call__(
                self._tr.transform(_np.asarray(value, dtype=float)), clip=clip)
        def inverse(self, value):
            return self._tr.inverted().transform(super().inverse(value))
    _ScaledNorm.__name__ = f"{base_norm_cls.__name__}From{scale_cls.__name__}"
    return _ScaledNorm


def same_color(c1, c2, *, tol=1e-7):
    """Equality test for two colour specs after normalizing to RGBA."""
    a = _np.asarray(to_rgba(c1), dtype=float)
    b = _np.asarray(to_rgba(c2), dtype=float)
    return bool(_np.all(_np.abs(a - b) < tol))


