import re as _re_colors


# Compiled regex that matches a hex colour spec (#RGB / #RGBA / #RRGGBB /
# #RRGGBBAA). Upstream exposes this so other modules can do quick
# colour-string detection.
hexColorPattern = _re_colors.compile(
    r'\A#(?:[0-9a-fA-F]{3}){1,2}(?:[0-9a-fA-F]{2})?\Z')


def hex2color(s):
    """Convert a hex colour string ``#RRGGBB`` (or ``#RGB``) to an
    ``(r, g, b)`` tuple of floats in [0, 1]. Strips alpha if present.
    """
    if not isinstance(s, str) or not s.startswith('#'):
        raise ValueError(f"invalid hex colour spec: {s!r}")
    h = s.lstrip('#')
    # Expand short form (#abc → #aabbcc).
    if len(h) in (3, 4):
        h = ''.join(c * 2 for c in h)
    if len(h) not in (6, 8):
        raise ValueError(f"invalid hex colour spec: {s!r}")
    r = int(h[0:2], 16) / 255.0
    g = int(h[2:4], 16) / 255.0
    b = int(h[4:6], 16) / 255.0
    return (r, g, b)


def rgb2hex(c, keep_alpha=False):
    """Convert an RGB(A) tuple of floats in [0, 1] to a hex string.
    If ``keep_alpha`` is True and the input is 4-tuple, the result
    includes the alpha channel as ``#RRGGBBAA``."""
    if not hasattr(c, '__len__'):
        raise ValueError(f"expected RGB or RGBA tuple, got {c!r}")
    rgb = [max(0, min(255, int(round(x * 255)))) for x in c[:3]]
    s = '#{:02x}{:02x}{:02x}'.format(*rgb)
    if keep_alpha and len(c) >= 4:
        a = max(0, min(255, int(round(c[3] * 255))))
        s += f'{a:02x}'
    return s


# ─── Added: missing methods on Normalize / Colormap ─────────────────


def _norm_process_value(self, value):
    """Convert input to an ndarray for normalisation. Returns
    ``(array, is_scalar)`` so callers can restore scalar output."""
    is_scalar = _np.isscalar(value)
    arr = _np.atleast_1d(value).astype(float)
    return arr, is_scalar


def _norm_clip_get(self):
    return getattr(self, '_clip_flag', False)


def _norm_clip_set(self, b):
    self._clip_flag = bool(b)


def _norm_vmin_get(self):
    # IMPORTANT: use ``is None`` test, not ``or`` — otherwise vmin=0 is
    # mis-treated as unset and silently overwritten with the fallback.
    v = getattr(self, '_vmin', None)
    return v


def _norm_vmin_set(self, v):
    self._vmin = v if v is None else float(v)


def _norm_vmax_get(self):
    v = getattr(self, '_vmax', None)
    return v


def _norm_vmax_set(self, v):
    self._vmax = v if v is None else float(v)


Normalize.process_value = _norm_process_value
Normalize.clip = property(_norm_clip_get, _norm_clip_set)
Normalize.vmin = property(_norm_vmin_get, _norm_vmin_set)
Normalize.vmax = property(_norm_vmax_get, _norm_vmax_set)


# Colormap methods — operate on the _Colormap class from matplotlib.cm.
def _attach_colormap_methods():
    from matplotlib.cm import _Colormap
    def copy(self):
        from matplotlib.cm import _Colormap as _C
        cm = _C(self.name)
        cm._stops = list(self._stops)
        cm._plotly_name = self._plotly_name
        return cm

    def get_bad(self):    return getattr(self, '_bad', (0, 0, 0, 0))
    def set_bad(self, color='k', alpha=None):
        self._bad = color

    def get_over(self):   return getattr(self, '_over', self._stops[-1])
    def set_over(self, color='k', alpha=None):
        self._over = color

    def get_under(self):  return getattr(self, '_under', self._stops[0])
    def set_under(self, color='k', alpha=None):
        self._under = color

    def set_extremes(self, *, bad=None, under=None, over=None):
        if bad is not None: self._bad = bad
        if under is not None: self._under = under
        if over is not None: self._over = over

    def with_extremes(self, *, bad=None, under=None, over=None):
        cm = self.copy()
        cm.set_extremes(bad=bad, under=under, over=over)
        return cm

    def is_gray(self):
        # All R/G/B stops equal → grayscale.
        return all(r == g == b for r, g, b in self._stops)

    _Colormap.copy = copy
    _Colormap.get_bad = get_bad
    _Colormap.set_bad = set_bad
    _Colormap.get_over = get_over
    _Colormap.set_over = set_over
    _Colormap.get_under = get_under
    _Colormap.set_under = set_under
    _Colormap.set_extremes = set_extremes
    _Colormap.with_extremes = with_extremes
    _Colormap.is_gray = is_gray
    # `resampled` already exists on _Colormap.


_attach_colormap_methods()


