def _ls_blend_hsv(self, rgb, intensity, hsv_max_sat=1, hsv_max_val=1,
                   hsv_min_val=0, hsv_min_sat=0):
    """Blend an RGB image with an intensity map via HSV."""
    import numpy as _np
    rgb = _np.asarray(rgb)
    intensity = _np.asarray(intensity)
    # Treat intensity as the V channel scaler.
    if rgb.ndim == 3:
        intensity = intensity[..., None]
    return _np.clip(rgb * intensity, 0, 1)


def _ls_blend_overlay(self, rgb, intensity):
    import numpy as _np
    rgb = _np.asarray(rgb); intensity = _np.asarray(intensity)
    if rgb.ndim == 3: intensity = intensity[..., None]
    out = _np.where(rgb < 0.5, 2 * rgb * intensity,
                     1 - 2 * (1 - rgb) * (1 - intensity))
    return _np.clip(out, 0, 1)


def _ls_blend_soft_light(self, rgb, intensity):
    import numpy as _np
    rgb = _np.asarray(rgb); intensity = _np.asarray(intensity)
    if rgb.ndim == 3: intensity = intensity[..., None]
    out = (1 - 2 * intensity) * rgb ** 2 + 2 * intensity * rgb
    return _np.clip(out, 0, 1)


def _ls_shade_normals(self, normals, fraction=1.0):
    """Project normals onto the light direction to get intensity."""
    import numpy as _np
    light = _np.asarray(self.direction)
    intensity = normals @ light
    return _np.clip(intensity * fraction, 0, 1)


LightSource.blend_hsv        = _ls_blend_hsv
LightSource.blend_overlay    = _ls_blend_overlay
LightSource.blend_soft_light = _ls_blend_soft_light
LightSource.shade_normals    = _ls_shade_normals


