# Each of these used to be a no-op stub. Replaced with the same math
# upstream uses so callers get correct values, not silent None returns.

# ColorConverter.colors – class attribute mapping name → RGB tuple.
# Upstream provides the BASE_COLORS dict here.
ColorConverter.colors = BASE_COLORS

# ListedColormap / LinearSegmentedColormap .resampled() – return a new
# colormap with N entries by re-sampling the lookup table.
def _lsc_resampled(self, lutsize):
    """Return a new LinearSegmentedColormap with ``lutsize`` entries by
    resampling the existing LUT linearly."""
    new = LinearSegmentedColormap(self.name, self._segmentdata, N=int(lutsize))
    return new
LinearSegmentedColormap.resampled = _lsc_resampled

def _lsc_set_gamma(self, gamma):
    """Apply a gamma correction to the LUT in place."""
    g = float(gamma)
    # Apply gamma to the [0,1] RGB channels.
    self._lut[:, :3] = _np.clip(self._lut[:, :3], 0.0, 1.0) ** g
    return self
LinearSegmentedColormap.set_gamma = _lsc_set_gamma

def _listed_resampled(self, lutsize):
    """Resample a ListedColormap by linearly indexing the colour list."""
    n = int(lutsize)
    if n == len(self.colors):
        return ListedColormap(list(self.colors), self.name)
    idx = _np.linspace(0, len(self.colors) - 1, n).astype(int)
    return ListedColormap([self.colors[i] for i in idx], self.name, N=n)
ListedColormap.resampled = _listed_resampled


